"""Package the measured shadow comparison; does not update any inventory consumer."""
import argparse,json,hashlib
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--experiment-root',type=Path,required=True);p.add_argument('--web-output',type=Path,required=True);a=p.parse_args();root=a.experiment_root
scores=json.loads((root/'long-scores.json').read_text());assert len(scores)==4,'Finish both paired month-long runs first'
bench={k:json.loads((root/folder/'results.json').read_text()) for k,folder in [('original','repro-baseline-bench'),('new','repro-bench')]}
package=dict(scores=scores,benchmark={k:{field:d[field] for field in ['median_wall','median_cpu','peak_rss_kib']} for k,d in bench.items()},event_spike=json.loads((root/'event-spike.json').read_text()))
a.web_output.write_text(json.dumps(package,indent=2))
lines=['# Endpoint v2: implementation and validation results','', 'Implemented in `adsbfi-proxy`; production ingestion and downstream consumers have **not** been switched. Full-history reingestion has **not** been run. Two complete 31-day shadow builds and a resumable offline migration tool are ready for review.','', '## Accuracy diagnostics','', 'Both variants read identical raw files and reference snapshots. Score the original top 100 airports on Jan 18–Feb 13, 2025 and Jul 22–Aug 17, 2026 (UTC), excluding the final hour. The four preceding days in each run were used during development and are excluded. No historical inventory offsets or fitted trends enter these metrics.','', '| Evaluation | Metric / 1,000 movements | Original | v2 | Change |','| --- | --- | ---: | ---: | ---: |']
for window in ['holdout-winter','holdout-event']:
 old=next(r for r in scores if r['variant']=='baseline-long' and r['window']==window);new=next(r for r in scores if r['variant']=='reproducible-long' and r['window']==window)
 for label,key in [('Absolute airport net','abs_net_per_1000'),('Repeated aircraft imbalance','excess_tail_per_1000')]:lines.append(f"| {window} | {label} | {old[key]:.2f} | {new[key]:.2f} | {(new[key]/old[key]-1)*100:+.1f}% |")
lines+=['','Absolute airport net is `sum(abs(landings − takeoffs)) / movements × 1000`. Repeated aircraft imbalance uses `sum(max(0, abs(net per aircraft/airport) − 1))` instead. They are diagnostics, **not measured precision/recall**. Real stock changes and asymmetric reception affect both. This is temporal validation plus inspected regressions, not a representative manually labeled holdout.','', '| Airport | Winter net/day original → v2 | Summer net/day original → v2 |','| --- | ---: | ---: |']
for code in ['KMIA','MMMX','RPLL','WIII','LTFM','KTEB']:
 values=[]
 for window in ['holdout-winter','holdout-event']:
  pair=[]
  for variant in ['baseline-long','reproducible-long']:
   r=next(r for r in scores if r['window']==window and r['variant']==variant);pair.append(next(x['net_per_day'] for x in r['airports'] if x['code']==code))
  values.append(f'{pair[0]:+.1f} → {pair[1]:+.1f}')
 lines.append('| '+code+' | '+' | '.join(values)+' |')
lines+=['','**Jakarta winter and Istanbul summer both regress substantially.** Do not treat these histories as reliable absolute counts. The independent ledger can expose one-sided observations previously hidden by pairing. Never infer the missing side merely to improve a drift score. Some other airports also regress; the interactive report exposes all 100.','', '## Performance','', '2026-09-18 15:00 UTC full-world heatmap, after six warmup files. Nine independent copied-checkpoint runs per binary; process startup, reference/state loading, parsing, inference and commits included. Bulk builders were stopped during the final comparison.','', '| Measurement | Original | v2 |','| --- | ---: | ---: |']
for label,key,scale,suffix in [('Median wall','median_wall',1000,'ms'),('Median CPU','median_cpu',1,'s'),('Peak RSS','peak_rss_kib',1/1024,'MiB')]:lines.append(f"| {label} | {bench['original'][key]*scale:.2f} {suffix} | {bench['new'][key]*scale:.2f} {suffix} |")
lines+=['','Wall time is effectively unchanged; CPU falls about 7% and peak memory about 19%. This measures the development machine, not the low-resource deployment target. Internal inference/commit stages do more work, offset by less startup/state overhead. Month-long build timings were not controlled performance trials and should not be interpreted as a speedup.','', 'Observed full-month builder times (not controlled trials): winter 201 → 246 seconds; summer 287 → 347 seconds. These backfills were about 21–22% slower even though the controlled one-file rolling update was unchanged.', '', 'Storage is the main resource tradeoff:', '']
for window in ['holdout-winter','holdout-event']:
 sizes=[(root/v/window/'events.sqlite').stat().st_size/1024**3 for v in ['baseline-long','reproducible-long']];lines.append(f'- {window}: {sizes[0]:.2f} → {sizes[1]:.2f} GiB for the ledger. Independent endpoint rows and evidence cost more disk than paired rows.')
lines+=['','## What changed','', '- Reject metadata/out-of-range coordinates in every Rust parser and the Python summarizer. Callsign bytes previously supplied fictitious altitude; the Calgary ground-only regression no longer produces endpoints.', '- Store independently supported takeoffs and landings with episode uniqueness and source evidence; remove pending pairing and paired-row generation.', '- Keep bounded terminal ground samples, prefer ground observations, and use aircraft-compatible airport candidates. Preserve water eligibility for unknown/general fixed-wing types and heliports for rotorcraft; small airports are not globally banned.', '- Share spatial indexes, cap caches, index processed-file lookups, shrink parser over-allocation, preserve exact checkpoint coordinates and use exact-position cache keys.', '- Add the insertion-ID endpoint feed/browser, fresh-schema/checkpoint guards, and offline resumable shadow backfill with reference snapshots and provenance.', '', '## Tests and inspected evidence','', '- 7 Rust tests and 21 Python tests pass, including metadata decoding across six parsers, compatibility controls, checkpoint precision, cursor semantics, replay deduplication, input gaps, provenance, old-schema rejection, and live cleanup.', '- Twelve complete heatmaps: continuous execution and restart after every file produce identical 84,292 endpoint records and 18,929 active track records. Endpoint insertion order can differ; movement identity and data match.', '- Five original real-aircraft replays: Miami/Manila/Mexico City assignments corrected; the Jakarta takeoff discarded by pairing is preserved; the Istanbul high-start climb remains unresolved.', '- Calgary example ICAO c1ea75: July 18 previously had four paired-flight rows; v2 has no endpoints that day. The parser regression directly tests the offending metadata record.', '- Endpoint browser tested for paging, filtering, retired paired route, mobile layout and browser errors. Offline backfill and resume tested on this external disk with real files.', '- July 19 Teterboro buildup from midnight: peak +68 → +71, and 21:30 UTC +48 → +49. This is relative movement, not known aircraft stock.', '', '## Rejected complexity and limitations','', 'A bounded trajectory extrapolator reduced Istanbul drift, but Jakarta winter changed from +1.4/day in the strict short-window ablation to +70.6/day with one direction sample and −47.3/day with two. Direction/coverage sensitivity was too high to ship. No runway/approach database or extrapolated endpoints are included.', '', 'Remaining limitations include high-start climbs, missing approach reception, short turns inside one heatmap, unknown/amphibious type ambiguity, historical reference changes, and heuristic confidence. The small-airport preference is not a reviewed site-identity map. There is no calibrated time interval or probability, and no guarantee that the historical minimum equals empty airport stock.', '', 'The implementation intentionally omits unproven geometry, canonical-site mergers, fitted drift correction and complex revision machinery. Rebuild into a new versioned ledger when inference changes. See [migration details](../ENDPOINT_V2.md).', '', '## Reproduction','', 'Experimental artifacts: `'+str(root)+'`. Benchmark binary SHA-256: `'+hashlib.sha256((root/'reproducible-builder').read_bytes()).hexdigest()+'`. Later source changes add regression tests only to the Rust builder; the release rebuild also passes full rolling parity.', '', '```sh','python3 benchmarks/single_file.py --binary /path/to/binary --output /fresh/benchmark --repeats 9','python3 benchmarks/panel.py --long --binary /path/to/binary --output /fresh/panel','python3 benchmarks/score_panel.py --warmup-days 4 --report /path/to/scores.json /old/panel /new/panel','python3 benchmarks/rolling_parity.py --binary /path/to/binary --output /fresh/parity','python3 benchmarks/real_cases.py --binary /path/to/binary --output /fresh/cases','```','', 'Do not copy shadow databases over production. Review these results, complete a separately stored full-archive backfill, then switch the worker and rebuild downstream consumers from endpoint ID zero. The downstream update is deliberately deferred.']
Path(__file__).with_name('RESULTS.md').write_text('\n'.join(lines)+'\n')
